def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    values: dict[str, int | str] = {}
    formulas: dict[str, str] = {}
    row_cells: list[list[tuple[int, str]]] = [[] for _ in range(100)]

    for name, content in cells.items():
        c = ord(name[0]) - 65
        r = int(name[1:])
        row_cells[r].append((c, name))
        s = content.strip()
        if s.startswith("="):
            formulas[name] = s[1:]
        else:
            values[name] = int(s)

    for row in row_cells:
        if len(row) > 1:
            row.sort()

    def tokenize(s: str) -> list[int | str | None]:
        tokens: list[int | str | None] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(int(s[i:j]))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and ("A" <= s[j] <= "Z" or s[j].isdigit()):
                    j += 1
                tokens.append(s[i:j])
                i = j
            elif ch == "<":
                if i + 1 < n and (s[i + 1] == ">" or s[i + 1] == "="):
                    tokens.append(s[i : i + 2])
                    i += 2
                else:
                    tokens.append("<")
                    i += 1
            elif ch == ">":
                if i + 1 < n and s[i + 1] == "=":
                    tokens.append(">=")
                    i += 2
                else:
                    tokens.append(">")
                    i += 1
            else:
                tokens.append(ch)
                i += 1
        tokens.append(None)
        return tokens

    def parse_formula(s: str) -> tuple:
        tokens = tokenize(s)
        pos = 0

        def parse_expr() -> tuple:
            nonlocal pos
            node = parse_term()
            while tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = ("bin", op, node, parse_term())
            return node

        def parse_term() -> tuple:
            nonlocal pos
            node = parse_unary()
            while tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = ("bin", op, node, parse_unary())
            return node

        def parse_unary() -> tuple:
            nonlocal pos
            if tokens[pos] == "-":
                pos += 1
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom() -> tuple:
            nonlocal pos
            tok = tokens[pos]
            if isinstance(tok, int):
                pos += 1
                return ("num", tok)
            if tok == "(":
                pos += 1
                node = parse_expr()
                pos += 1  # ')'
                return node
            pos += 1
            if tokens[pos] == "(":
                pos += 1  # '('
                if tok == "IF":
                    left = parse_expr()
                    op = tokens[pos]
                    pos += 1
                    right = parse_expr()
                    pos += 1  # ','
                    then_e = parse_expr()
                    pos += 1  # ','
                    else_e = parse_expr()
                    pos += 1  # ')'
                    return ("if", op, left, right, then_e, else_e)
                args = []
                while True:
                    t0 = tokens[pos]
                    if isinstance(t0, str) and "A" <= t0[0] <= "Z" and tokens[pos + 1] == ":":
                        t1 = tokens[pos + 2]
                        pos += 3
                        c1 = ord(t0[0]) - 65
                        r1 = int(t0[1:])
                        c2 = ord(t1[0]) - 65
                        r2 = int(t1[1:])
                        if c1 > c2:
                            c1, c2 = c2, c1
                        if r1 > r2:
                            r1, r2 = r2, r1
                        args.append(("range", r1, r2, c1, c2))
                    else:
                        args.append(parse_expr())
                    if tokens[pos] == ",":
                        pos += 1
                    else:
                        pos += 1  # ')'
                        break
                return ("agg", tok, args)
            return ("cell", tok)

        return parse_expr()

    def iter_agg_nodes(args: list[tuple]):
        for arg in args:
            if arg[0] == "range":
                _, r1, r2, c1, c2 = arg
                for r in range(r1, r2 + 1):
                    for c, cname in row_cells[r]:
                        if c1 <= c <= c2:
                            yield ("cell", cname)
            else:
                yield arg

    in_progress: set[str] = set()

    def eval_cell(start_name: str) -> None:
        in_progress.add(start_name)
        stack: list[tuple] = [("CELL_DONE", start_name)]
        cur: tuple | None = parse_formula(formulas[start_name])
        val: int | str | None = None

        while True:
            if cur is not None:
                tag = cur[0]
                if tag == "num":
                    val = cur[1]
                    cur = None
                elif tag == "cell":
                    cname = cur[1]
                    if cname in values:
                        val = values[cname]
                        cur = None
                    elif cname in in_progress:
                        val = "#CYCLE!"
                        cur = None
                    elif cname not in cells:
                        val = 0
                        cur = None
                    else:
                        in_progress.add(cname)
                        stack.append(("CELL_DONE", cname))
                        cur = parse_formula(formulas[cname])
                elif tag == "neg":
                    stack.append(("NEG",))
                    cur = cur[1]
                elif tag == "bin":
                    _, op, left, right = cur
                    stack.append(("BIN_L", op, right))
                    cur = left
                elif tag == "if":
                    _, op, left, right, then_e, else_e = cur
                    stack.append(("IF_L", op, right, then_e, else_e))
                    cur = left
                else:  # "agg"
                    _, fn, args = cur
                    stack.append(("AGG", fn, iter_agg_nodes(args), None))
                    cur = None
                    val = None
            else:
                if not stack:
                    break
                frame = stack.pop()
                ftag = frame[0]
                if ftag == "CELL_DONE":
                    cname = frame[1]
                    in_progress.remove(cname)
                    values[cname] = val  # type: ignore[assignment]
                elif ftag == "NEG":
                    if isinstance(val, int):
                        val = -val
                elif ftag == "BIN_L":
                    if not isinstance(val, str):
                        _, op, right = frame
                        stack.append(("BIN_R", op, val))
                        cur = right
                elif ftag == "BIN_R":
                    if not isinstance(val, str):
                        _, op, lval = frame
                        if op == "+":
                            val = lval + val
                        elif op == "-":
                            val = lval - val
                        elif op == "*":
                            val = lval * val
                        else:
                            if val == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(lval) // abs(val)
                                val = -q if (lval < 0) ^ (val < 0) else q
                elif ftag == "IF_L":
                    if not isinstance(val, str):
                        _, op, right, then_e, else_e = frame
                        stack.append(("IF_R", op, val, then_e, else_e))
                        cur = right
                elif ftag == "IF_R":
                    if not isinstance(val, str):
                        _, op, lval, then_e, else_e = frame
                        if op == "=":
                            cond = lval == val
                        elif op == "<>":
                            cond = lval != val
                        elif op == "<":
                            cond = lval < val
                        elif op == "<=":
                            cond = lval <= val
                        elif op == ">":
                            cond = lval > val
                        else:
                            cond = lval >= val
                        cur = then_e if cond else else_e
                else:  # "AGG"
                    _, fn, it, acc = frame
                    if isinstance(val, str):
                        continue
                    if val is not None:
                        if acc is None:
                            acc = val
                        elif fn == "SUM":
                            acc += val
                        elif fn == "MIN":
                            if val < acc:
                                acc = val
                        else:
                            if val > acc:
                                acc = val
                    while True:
                        nxt = next(it, None)
                        if nxt is None:
                            val = 0 if acc is None else acc
                            break
                        if nxt[0] == "cell":
                            cname = nxt[1]
                            if cname in values:
                                v = values[cname]
                                if isinstance(v, str):
                                    val = v
                                    break
                                if acc is None:
                                    acc = v
                                elif fn == "SUM":
                                    acc += v
                                elif fn == "MIN":
                                    if v < acc:
                                        acc = v
                                else:
                                    if v > acc:
                                        acc = v
                                continue
                        stack.append(("AGG", fn, it, acc))
                        cur = nxt
                        break

    for name in formulas:
        if name not in values:
            eval_cell(name)

    return values
